// Block (composition) — a filterable command list inside a controlled Dialog overlay.
// Dialog owns overlay/focus/dismissal; Autocomplete + Menu own filtering and list behavior.
// The list is a trigger-less Menu — commands are actions (onAction), so the RAC-canonical
// command-palette collection is Menu, not ListBox; it renders bare (no Popover surface) because
// the surrounding Dialog already owns the floating surface.
// The global Command/Ctrl+K shortcut is the only behavior orchestrated by this Block.
import { useCallback, useEffect, useState, type ReactNode } from "react";
import { Autocomplete } from "../components/Autocomplete";
import { DialogContent, DialogHeader, DialogTitle } from "../components/Dialog";
import { Keyboard } from "../components/Keyboard";
import { Menu, MenuItem, MenuSection } from "../components/Menu";
import { SearchField } from "../components/SearchField";
import { Stack } from "../layouts/Stack";
import "./CommandMenu.css";

export interface CommandMenuProps {
  commands: {
    id: string;
    label: string;
    group?: string;
    keywords?: string;
    /** A leading glyph, as a design tool's action list marks each command. */
    icon?: ReactNode;
    /** The key that runs it outside the menu, shown at the row's end ("⌘D"). */
    shortcut?: string;
    /** Listed but not runnable now, with `note` saying why ("Nothing selected"). */
    isDisabled?: boolean;
    note?: string;
  }[];
  onAction: (id: string) => void;
  isOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** The dialog's title, which also names the command list. */
  title?: string;
  placeholder?: string;
  enableShortcut?: boolean;
}

export function CommandMenu({
  commands,
  onAction,
  isOpen,
  onOpenChange,
  title = "Command menu",
  placeholder = "Type a command or search…",
  enableShortcut = true,
}: CommandMenuProps) {
  const [internalIsOpen, setInternalIsOpen] = useState(false);
  const open = isOpen ?? internalIsOpen;

  const handleOpenChange = useCallback(
    (nextOpen: boolean) => {
      if (isOpen === undefined) setInternalIsOpen(nextOpen);
      onOpenChange?.(nextOpen);
    },
    [isOpen, onOpenChange],
  );

  useEffect(() => {
    if (!enableShortcut) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      // By the key's place, not its letter: under a Korean input source K reads "ㅏ".
      if ((event.metaKey || event.ctrlKey) && event.code === "KeyK") {
        event.preventDefault();
        handleOpenChange(!open);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [enableShortcut, handleOpenChange, open]);

  const handleAction = (id: string) => {
    onAction(id);
    handleOpenChange(false);
  };

  const groups = new Map<string | undefined, typeof commands>();
  for (const command of commands) {
    const group = command.group;
    const items = groups.get(group);
    if (items) items.push(command);
    else groups.set(group, [command]);
  }
  const hasGroups = commands.some((command) => command.group !== undefined);

  const renderCommand = (command: CommandMenuProps["commands"][number]) => (
    <MenuItem
      key={command.id}
      id={command.id}
      textValue={[command.label, command.keywords].filter(Boolean).join(" ")}
      onAction={() => handleAction(command.id)}
      icon={command.icon}
      isDisabled={command.isDisabled}
      trailing={
        command.note || command.shortcut ? (
          <>
            {command.note && <span className="sd-commandmenu__note sd-type-caption-medium">{command.note}</span>}
            {command.shortcut && <Keyboard>{command.shortcut}</Keyboard>}
          </>
        ) : undefined
      }
      className="sd-commandmenu__item"
    >
      {command.label}
    </MenuItem>
  );

  return (
    <DialogContent isOpen={open} onOpenChange={handleOpenChange} className="sd-commandmenu"
      header={
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
        </DialogHeader>
      }
    >
      <Autocomplete
        filter={(textValue, inputValue) =>
          textValue.toLocaleLowerCase().includes(inputValue.trim().toLocaleLowerCase())
        }
      >
        <Stack gap="small" className="sd-commandmenu__layout">
          <SearchField
            aria-label={placeholder}
            placeholder={placeholder}
            autoFocus
            className="sd-commandmenu__search"
          />
          <Menu aria-label={title} className="sd-commandmenu__list">
            {hasGroups
              ? [...groups].map(([group, groupCommands], index) => (
                  <MenuSection
                    key={`command-group-${index}`}
                    id={`command-group-${index}`}
                    title={group}
                    className="sd-commandmenu__section"
                  >
                    {groupCommands.map(renderCommand)}
                  </MenuSection>
                ))
              : commands.map(renderCommand)}
          </Menu>
        </Stack>
      </Autocomplete>
    </DialogContent>
  );
}

/* CommandMenu.css — .sd-commandmenu (Block)
   Stack arranges the search field and command list; Dialog, SearchField, and
   Menu own all chrome and interaction states. This Block defines no tokens.

   Real layout the primitives can't express: the command list scrolls within a
   bounded height so a long command set never grows the dialog past the viewport
   (a command palette must stay put and scroll internally). */
.sd-commandmenu__list {
  max-height: min(60vh, 24rem);
  overflow-y: auto;
}

/* Why a command cannot run now, beside its shortcut: a supporting line, so the muted ink (block-contract.md
   § 5, a Block's own text takes a Sys text role). */
.sd-commandmenu__note {
  color: var(--sd-color-text-muted);
}
